// Узел «Следующий пост»: первый пост из очереди, если сейчас можно публиковать.
// Тихие часы, интервал между публикациями и число попыток в src/publish.config.json.
// Пустой выход (нечего или рано публиковать) завершает запуск без отправки.
// Площадка из поля PLATFORM в «Настройках»: telegram (по умолчанию) или vk.
// src/queue.js (вклеено scripts/build-workflows.js, править в src/)
const queueLib = (() => {
  const module = { exports: {} };
// Очередь публикации поверх журнала log.js: какой пост отправить в канал следующим
// и что делать, если Телеграм его не принял. Та же база, что у createLog
// (node:sqlite или better-sqlite3); вызывать init() после log.init().
'use strict';

const TIME = /^([01]\d|2[0-3]):([0-5]\d)$/;
const toMinutes = (s) => {
  const m = String(s).match(TIME);
  if (!m) throw new Error(`время в виде ЧЧ:ММ, получено: ${s}`);
  return Number(m[1]) * 60 + Number(m[2]);
};

// Настройки из publish.config.json с проверкой и значениями по умолчанию.
function checkPublishConfig(config = {}) {
  const minIntervalMinutes = Number(config.minIntervalMinutes ?? 60);
  if (!Number.isFinite(minIntervalMinutes) || minIntervalMinutes < 0) throw new Error('minIntervalMinutes: число от 0');
  const maxAttempts = Number(config.maxAttempts ?? 3);
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) throw new Error('maxAttempts: целое от 1');
  const timeZone = config.timeZone || 'Europe/Moscow';
  // Неизвестный часовой пояс Intl отвергает сразу.
  new Intl.DateTimeFormat('en-GB', { timeZone });
  const quietHours = config.quietHours
    ? { from: toMinutes(config.quietHours.from), to: toMinutes(config.quietHours.to) }
    : null;
  return { minIntervalMinutes, maxAttempts, timeZone, quietHours };
}

// Попадает ли момент ms в тихие часы { from, to } (минуты от полуночи) по местному времени.
// from > to: интервал через полночь (23:00–08:00); from == to: тихих часов нет.
function inQuietHours(ms, quiet, timeZone) {
  if (quiet.from === quiet.to) return false;
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(ms));
  const part = (type) => Number(parts.find((p) => p.type === type).value);
  const m = part('hour') * 60 + part('minute');
  return quiet.from < quiet.to ? m >= quiet.from && m < quiet.to : m >= quiet.from || m < quiet.to;
}

function createQueue(db, options = {}) {
  if (!db || typeof db.exec !== 'function' || typeof db.prepare !== 'function') {
    throw new TypeError('нужен объект базы с exec и prepare');
  }
  const now = options.now || (() => new Date().toISOString());
  const byId = (id) => db.prepare('SELECT * FROM items WHERE id = ?').get(Number(id)) || null;

  // Счётчик неудачных отправок; журнал без него получает столбец с нулём.
  // false: журнала ещё нет (конвейер сбора не запускался), публиковать нечего.
  // Журнал прежней схемы переносит log.init(), до этого очередь его не трогает.
  function init() {
    const table = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'items'").get();
    if (!table) return false;
    if (!String(table.sql).includes("'queued'")) throw new Error('журнал прежней схемы: сначала log.init()');
    const cols = db.prepare('PRAGMA table_info(items)').all().map((c) => c.name);
    if (!cols.includes('attempts')) db.exec('ALTER TABLE items ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0');
    return true;
  }

  // Следующий пост или причина подождать: { item, wait }, где wait = null (можно отправлять),
  // 'quiet' (тихие часы), 'interval' (с прошлой публикации меньше minIntervalMinutes),
  // 'empty' (в очереди нечего отправлять). Первым идёт поставленный в очередь раньше.
  // Пост, который Телеграм не принял maxAttempts раз, остаётся в очереди с ошибкой,
  // но пропускается, чтобы не держать остальные.
  function next(config = {}) {
    const cfg = checkPublishConfig(config);
    const ms = Date.parse(now());
    if (cfg.quietHours && inQuietHours(ms, cfg.quietHours, cfg.timeZone)) return { item: null, wait: 'quiet' };
    const last = db.prepare("SELECT MAX(published_at) AS t FROM items WHERE status = 'published'").get();
    if (last && last.t && ms - Date.parse(last.t) < cfg.minIntervalMinutes * 60000) {
      return { item: null, wait: 'interval' };
    }
    const item =
      db
        .prepare(
          `SELECT * FROM items WHERE status = 'queued' AND post IS NOT NULL AND attempts < ?
           ORDER BY queued_at, id LIMIT 1`
        )
        .get(cfg.maxAttempts) || null;
    return { item, wait: item ? null : 'empty' };
  }

  // Площадка не приняла пост: он остаётся в очереди, в reason ошибка, счётчик растёт.
  // platform: telegram (по умолчанию) или vk, от неё зависит подпись ошибки.
  function failed(id, error, platform = 'telegram') {
    const old = byId(id);
    if (!old) throw new Error(`нет в журнале: ${id}`);
    if (old.status !== 'queued') throw new Error(`ошибка отправки только для queued, сейчас ${old.status}`);
    const text = String(error ?? '').trim().slice(0, 300) || 'неизвестная ошибка';
    db.prepare('UPDATE items SET reason = ?, attempts = attempts + 1, updated_at = ? WHERE id = ?').run(
      (platform === 'vk' ? 'ошибка ВКонтакте: ' : 'ошибка Телеграма: ') + text,
      now(),
      old.id
    );
    return byId(old.id);
  }

  // Площадка приняла пост: статус published и номер сообщения в канале (у ВКонтакте номер записи на стене), ошибка стирается.
  // Те же правила, что у log.published, только по номеру записи из узла «Следующий пост».
  function published(id, messageId) {
    if (messageId === undefined || messageId === null || String(messageId).trim() === '') {
      throw new Error('нет номера сообщения в канале');
    }
    const old = byId(id);
    if (!old) throw new Error(`нет в журнале: ${id}`);
    if (old.status !== 'queued') throw new Error(`публикация только из queued, сейчас ${old.status}`);
    const t = now();
    db.prepare(
      `UPDATE items SET status = 'published', message_id = ?, reason = NULL, published_at = ?, updated_at = ?
       WHERE id = ?`
    ).run(String(messageId), t, t, old.id);
    return byId(old.id);
  }

  return { init, next, failed, published };
}

if (typeof module !== 'undefined') {
  module.exports = { checkPublishConfig, inQuietHours, createQueue };
}
  return module.exports;
})();
// src/post.js (вклеено scripts/build-workflows.js, править в src/)
const postLib = (() => {
  const module = { exports: {} };
// Сборка поста из ответа нейросети: Телеграм и MAX (разметка HTML) или ВКонтакте (простой текст).
// Файл без зависимостей: функции можно вставить в узел Code n8n целиком.
// Разметка HTML (parse_mode: 'HTML'): в ней экранировать нужно только &, < и >.
'use strict';

// Лимит Телеграма на текст сообщения: 4096 знаков после разбора разметки,
// подпись к картинке 1024. Считается в единицах UTF-16, как у String.length.
const TELEGRAM_TEXT_LIMIT = 4096;
const TELEGRAM_CAPTION_LIMIT = 1024;

// ВКонтакте: метод wall.post, текст в параметре message, разметка не поддерживается.
// Документация метода: https://dev.vk.com/ru/method/wall.post
// Предел длины message в описании метода не указан, поэтому здесь свой предел
// с запасом. Поменять можно через options.limit.
const VK_TEXT_LIMIT = 4096;

// MAX: метод POST /messages, текст до 4000 знаков, разметка по полю format
// (markdown или html). Документация: https://dev.max.ru/docs-api/methods/POST/messages
// Теги HTML: https://dev.max.ru/docs-api/use-cases/sending-messages/text-formatting
// Учитывается ли разметка в пределе, не сказано, поэтому длина считается по всему
// тексту вместе с тегами.
const MAX_TEXT_LIMIT = 4000;
const MAX_FORMAT = 'html';

// Площадки, для которых есть сборка поста и промпт prompts/<площадка>.md.
const PLATFORMS = ['telegram', 'vk', 'max'];

function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeAttr(s) {
  return escapeHtml(s).replace(/"/g, '&quot;');
}

// Ссылка на источник обязательна: без неё или с нечитаемой ссылкой пост не собирается.
function sourceUrl(link) {
  let u;
  try {
    u = new URL(String(link || '').trim());
  } catch {
    throw new Error('нет ссылки на источник');
  }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('ссылка на источник не http(s)');
  return u;
}

// Обрезает текст до limit знаков: по концу предложения, если он не слишком
// далеко, иначе по пробелу, и ставит многоточие. Суррогатные пары не рвёт.
function truncate(text, limit) {
  const s = String(text ?? '').trim();
  if (s.length <= limit) return s;
  if (limit <= 1) return '…'.slice(0, Math.max(0, limit));
  let cut = s.slice(0, limit - 1);
  if (/[\uD800-\uDBFF]$/.test(cut)) cut = cut.slice(0, -1);
  const sentence = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentence >= cut.length * 0.6) return cut.slice(0, sentence + 1);
  const space = cut.lastIndexOf(' ');
  if (space >= cut.length * 0.6) cut = cut.slice(0, space);
  return cut.replace(/[\s,;:.\-]+$/, '') + '…';
}

// Собирает пост: заголовок жирным, текст, ссылка на источник отдельной строкой.
// Длина считается по видимому тексту (без тегов, сущности как один знак).
// options.caption: true, если пост идёт подписью к картинке (лимит 1024).
function buildPost({ title, text, link, sourceName } = {}, options = {}) {
  const url = sourceUrl(link);
  const limit = options.limit ?? (options.caption ? TELEGRAM_CAPTION_LIMIT : TELEGRAM_TEXT_LIMIT);
  const name = String(sourceName || '').trim() || url.hostname.replace(/^www\./, '');
  const head = String(title || '').trim();
  const body = String(text || '').trim();
  if (!body) throw new Error('пустой текст поста');

  const sourceLine = `Источник: ${name}`;
  const fixed = (head ? head.length + 2 : 0) + 2 + sourceLine.length;
  const room = limit - fixed;
  if (room < 20) throw new Error('не хватает места для текста поста');
  const visibleBody = truncate(body, room);

  const html =
    (head ? `<b>${escapeHtml(head)}</b>\n\n` : '') +
    `${escapeHtml(visibleBody)}\n\n` +
    `Источник: <a href="${escapeAttr(url.href)}">${escapeHtml(name)}</a>`;
  const visibleLength = (head ? head.length + 2 : 0) + visibleBody.length + 2 + sourceLine.length;
  return { text: html, parse_mode: 'HTML', visibleLength, truncated: visibleBody !== body };
}

// Пост для ВКонтакте: простой текст без HTML. Заголовок первой строкой,
// затем текст и подпись источника, ссылка последней отдельной строкой
// (ВКонтакте сам делает её кликабельной). Длина считается по всему тексту.
function buildVkPost({ title, text, link, sourceName } = {}, options = {}) {
  const url = sourceUrl(link);
  const limit = options.limit ?? VK_TEXT_LIMIT;
  const name = String(sourceName || '').trim() || url.hostname.replace(/^www\./, '');
  const head = String(title || '').replace(/\s+/g, ' ').trim();
  const body = String(text || '').replace(/\r\n?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!body) throw new Error('пустой текст поста');

  const tail = `Источник: ${name}\n${url.href}`;
  const fixed = (head ? head.length + 2 : 0) + 2 + tail.length;
  const room = limit - fixed;
  if (room < 20) throw new Error('не хватает места для текста поста');
  const visibleBody = truncate(body, room);

  const out = (head ? `${head}\n\n` : '') + `${visibleBody}\n\n${tail}`;
  return { text: out, visibleLength: out.length, truncated: visibleBody !== body };
}

// Пост для MAX: та же разметка HTML, что у Телеграма (<b> и <a> есть в обоих),
// заголовок жирным, текст, ссылка на источник отдельной строкой. Отправляется
// с format: 'html'. Длина считается по всему тексту с тегами и сущностями.
function buildMaxPost({ title, text, link, sourceName } = {}, options = {}) {
  const url = sourceUrl(link);
  const limit = options.limit ?? MAX_TEXT_LIMIT;
  const name = String(sourceName || '').trim() || url.hostname.replace(/^www\./, '');
  const head = String(title || '').replace(/\s+/g, ' ').trim();
  const body = String(text || '').replace(/\r\n?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!body) throw new Error('пустой текст поста');

  const headHtml = head ? `<b>${escapeHtml(head)}</b>\n\n` : '';
  const tail = `\n\nИсточник: <a href="${escapeAttr(url.href)}">${escapeHtml(name)}</a>`;
  const room = limit - headHtml.length - tail.length;
  if (room < 20) throw new Error('не хватает места для текста поста');
  // Экранирование удлиняет текст, поэтому обрезка повторяется, пока он не влезет.
  let visibleBody = truncate(body, room);
  while (escapeHtml(visibleBody).length > room) {
    visibleBody = truncate(body, visibleBody.length - (escapeHtml(visibleBody).length - room));
  }
  const out = headHtml + escapeHtml(visibleBody) + tail;
  return { text: out, format: MAX_FORMAT, visibleLength: out.length, truncated: visibleBody !== body };
}

// Площадка из поля PLATFORM узла «Настройки»; пусто значит telegram.
function platformOf(settings = {}) {
  const p = String((settings && settings.PLATFORM) ?? '').trim().toLowerCase() || 'telegram';
  if (!PLATFORMS.includes(p)) throw new Error(`неизвестная площадка: ${p}`);
  return p;
}

// Сборка поста для выбранной площадки.
function buildPostFor(platform, fields, options = {}) {
  if (platform === 'vk') return buildVkPost(fields, options);
  if (platform === 'max') return buildMaxPost(fields, options);
  if (platform === 'telegram') return buildPost(fields, options);
  throw new Error(`неизвестная площадка: ${platform}`);
}

// Подставляет поля новости в шаблон промпта: {{title}}, {{description}}, {{link}}, {{maxLength}}.
// Неизвестная подстановка остаётся видимой, чтобы ошибку в шаблоне было легко заметить.
function fillPrompt(template, vars = {}) {
  return String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) =>
    Object.prototype.hasOwnProperty.call(vars, k) ? String(vars[k] ?? '') : m
  );
}

if (typeof module !== 'undefined') {
  module.exports = {
    TELEGRAM_TEXT_LIMIT,
    TELEGRAM_CAPTION_LIMIT,
    VK_TEXT_LIMIT,
    MAX_TEXT_LIMIT,
    MAX_FORMAT,
    PLATFORMS,
    escapeHtml,
    truncate,
    buildPost,
    buildVkPost,
    buildMaxPost,
    buildPostFor,
    platformOf,
    fillPrompt,
  };
}
  return module.exports;
})();
// src/plain.js (вклеено scripts/build-workflows.js, править в src/)
const plainLib = (() => {
  const module = { exports: {} };
// Перевод поста из разметки HTML Телеграма в простой текст для ВКонтакте и выбор текста под площадку.
// Файл без зависимостей: вклеивается в узел Code n8n целиком.
'use strict';

// Черновик из журнала, собранный для Телеграма (HTML), в простой текст для ВКонтакте:
// <b> и прочие теги убираются, ссылка источника переносится на отдельную строку,
// сущности &amp; &lt; &gt; &quot; раскрываются. Текст без тегов возвращается как есть.
function htmlToPlain(html) {
  const s = String(html ?? '');
  if (!/<\/?[a-z][^>]*>/i.test(s)) return s.trim();
  const unescape = (t) =>
    t.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  return unescape(
    s
      .replace(/<a\s[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/gi, (m, href, text) => `${text}\n${href}`)
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/?[a-z][^>]*>/gi, '')
  ).trim();
}

// Черновик собран для Телеграма, если в нём есть теги разметки HTML (buildPost всегда
// ставит <b> и <a>). Пост для ВКонтакте собирается простым текстом без тегов.
// Площадка в журнал не пишется: её видно по самому тексту, и переписанный по кнопке
// черновик (он всегда в HTML) определяется так же.
function isTelegramPost(text) {
  return /<\/?[a-z][^>]*>/i.test(String(text ?? ''));
}

function escapeHtml(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Текст поста для отправки на площадку platform из черновика журнала.
// vk: черновик Телеграма переводится в простой текст, пост ВКонтакте уходит как есть.
// telegram: пост ВКонтакте экранируется под parse_mode HTML, черновик Телеграма как есть.
function textFor(platform, post) {
  const telegram = isTelegramPost(post);
  if (platform === 'vk') return telegram ? htmlToPlain(post) : String(post ?? '').trim();
  return telegram ? String(post) : escapeHtml(String(post ?? '').trim());
}

if (typeof module !== 'undefined') module.exports = { htmlToPlain, isTelegramPost, textFor };
  return module.exports;
})();
// src/publish.config.json (вклеено scripts/build-workflows.js, править в src/)
const CONFIG = {"minIntervalMinutes":60,"quietHours":{"from":"23:00","to":"08:00"},"timeZone":"Europe/Moscow","maxAttempts":3};

const { DatabaseSync } = require('node:sqlite');
const settings = $('Настройки').first().json;
const platform = postLib.platformOf(settings);
if (platform !== 'telegram' && platform !== 'vk') throw new Error(`публикация на площадку ${platform} пока не поддерживается`);

// Для ВКонтакте нужен номер сообщества: запись уходит на стену с owner_id = -номер.
let ownerId = '';
if (platform === 'vk') {
  const group = String(settings.VK_GROUP_ID ?? '').trim().replace(/^-/, '');
  if (!/^\d+$/.test(group)) throw new Error('в «Настройках» нужен VK_GROUP_ID: номер сообщества цифрами');
  ownerId = '-' + group;
}

const db = new DatabaseSync(settings.CF_DB_PATH);
try {
  const queue = queueLib.createQueue(db);
  // Журнала ещё нет: конвейер сбора не запускался.
  if (!queue.init()) return [];
  const { item } = queue.next(CONFIG);
  if (!item) return [];
  // Черновик собран под площадку сбора; если она другая, текст переводится (src/plain.js).
  const text = plainLib.textFor(platform, item.post);
  return [{ json: { id: item.id, link: item.link, text, platform, ownerId } }];
} finally {
  db.close();
}

// Узел «Итог»: ответ площадки -> журнал. Есть номер сообщения: пост опубликован.
// Ошибка Телеграма или ВКонтакте пишется в журнал, пост остаётся в очереди до следующего запуска.
// Журнал уже подготовлен узлом «Следующий пост» (queue.init).
// src/queue.js (вклеено scripts/build-workflows.js, править в src/)
const queueLib = (() => {
  const module = { exports: {} };
// Очередь публикации поверх журнала log.js: какой пост отправить в канал следующим
// и что делать, если Телеграм его не принял. Та же база, что у createLog
// (node:sqlite или better-sqlite3); вызывать init() после log.init().
'use strict';

const TIME = /^([01]\d|2[0-3]):([0-5]\d)$/;
const toMinutes = (s) => {
  const m = String(s).match(TIME);
  if (!m) throw new Error(`время в виде ЧЧ:ММ, получено: ${s}`);
  return Number(m[1]) * 60 + Number(m[2]);
};

// Настройки из publish.config.json с проверкой и значениями по умолчанию.
function checkPublishConfig(config = {}) {
  const minIntervalMinutes = Number(config.minIntervalMinutes ?? 60);
  if (!Number.isFinite(minIntervalMinutes) || minIntervalMinutes < 0) throw new Error('minIntervalMinutes: число от 0');
  const maxAttempts = Number(config.maxAttempts ?? 3);
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) throw new Error('maxAttempts: целое от 1');
  const timeZone = config.timeZone || 'Europe/Moscow';
  // Неизвестный часовой пояс Intl отвергает сразу.
  new Intl.DateTimeFormat('en-GB', { timeZone });
  const quietHours = config.quietHours
    ? { from: toMinutes(config.quietHours.from), to: toMinutes(config.quietHours.to) }
    : null;
  return { minIntervalMinutes, maxAttempts, timeZone, quietHours };
}

// Попадает ли момент ms в тихие часы { from, to } (минуты от полуночи) по местному времени.
// from > to: интервал через полночь (23:00–08:00); from == to: тихих часов нет.
function inQuietHours(ms, quiet, timeZone) {
  if (quiet.from === quiet.to) return false;
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(new Date(ms));
  const part = (type) => Number(parts.find((p) => p.type === type).value);
  const m = part('hour') * 60 + part('minute');
  return quiet.from < quiet.to ? m >= quiet.from && m < quiet.to : m >= quiet.from || m < quiet.to;
}

function createQueue(db, options = {}) {
  if (!db || typeof db.exec !== 'function' || typeof db.prepare !== 'function') {
    throw new TypeError('нужен объект базы с exec и prepare');
  }
  const now = options.now || (() => new Date().toISOString());
  const byId = (id) => db.prepare('SELECT * FROM items WHERE id = ?').get(Number(id)) || null;

  // Счётчик неудачных отправок; журнал без него получает столбец с нулём.
  // false: журнала ещё нет (конвейер сбора не запускался), публиковать нечего.
  // Журнал прежней схемы переносит log.init(), до этого очередь его не трогает.
  function init() {
    const table = db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'items'").get();
    if (!table) return false;
    if (!String(table.sql).includes("'queued'")) throw new Error('журнал прежней схемы: сначала log.init()');
    const cols = db.prepare('PRAGMA table_info(items)').all().map((c) => c.name);
    if (!cols.includes('attempts')) db.exec('ALTER TABLE items ADD COLUMN attempts INTEGER NOT NULL DEFAULT 0');
    return true;
  }

  // Следующий пост или причина подождать: { item, wait }, где wait = null (можно отправлять),
  // 'quiet' (тихие часы), 'interval' (с прошлой публикации меньше minIntervalMinutes),
  // 'empty' (в очереди нечего отправлять). Первым идёт поставленный в очередь раньше.
  // Пост, который Телеграм не принял maxAttempts раз, остаётся в очереди с ошибкой,
  // но пропускается, чтобы не держать остальные.
  function next(config = {}) {
    const cfg = checkPublishConfig(config);
    const ms = Date.parse(now());
    if (cfg.quietHours && inQuietHours(ms, cfg.quietHours, cfg.timeZone)) return { item: null, wait: 'quiet' };
    const last = db.prepare("SELECT MAX(published_at) AS t FROM items WHERE status = 'published'").get();
    if (last && last.t && ms - Date.parse(last.t) < cfg.minIntervalMinutes * 60000) {
      return { item: null, wait: 'interval' };
    }
    const item =
      db
        .prepare(
          `SELECT * FROM items WHERE status = 'queued' AND post IS NOT NULL AND attempts < ?
           ORDER BY queued_at, id LIMIT 1`
        )
        .get(cfg.maxAttempts) || null;
    return { item, wait: item ? null : 'empty' };
  }

  // Площадка не приняла пост: он остаётся в очереди, в reason ошибка, счётчик растёт.
  // platform: telegram (по умолчанию) или vk, от неё зависит подпись ошибки.
  function failed(id, error, platform = 'telegram') {
    const old = byId(id);
    if (!old) throw new Error(`нет в журнале: ${id}`);
    if (old.status !== 'queued') throw new Error(`ошибка отправки только для queued, сейчас ${old.status}`);
    const text = String(error ?? '').trim().slice(0, 300) || 'неизвестная ошибка';
    db.prepare('UPDATE items SET reason = ?, attempts = attempts + 1, updated_at = ? WHERE id = ?').run(
      (platform === 'vk' ? 'ошибка ВКонтакте: ' : 'ошибка Телеграма: ') + text,
      now(),
      old.id
    );
    return byId(old.id);
  }

  // Площадка приняла пост: статус published и номер сообщения в канале (у ВКонтакте номер записи на стене), ошибка стирается.
  // Те же правила, что у log.published, только по номеру записи из узла «Следующий пост».
  function published(id, messageId) {
    if (messageId === undefined || messageId === null || String(messageId).trim() === '') {
      throw new Error('нет номера сообщения в канале');
    }
    const old = byId(id);
    if (!old) throw new Error(`нет в журнале: ${id}`);
    if (old.status !== 'queued') throw new Error(`публикация только из queued, сейчас ${old.status}`);
    const t = now();
    db.prepare(
      `UPDATE items SET status = 'published', message_id = ?, reason = NULL, published_at = ?, updated_at = ?
       WHERE id = ?`
    ).run(String(messageId), t, t, old.id);
    return byId(old.id);
  }

  return { init, next, failed, published };
}

if (typeof module !== 'undefined') {
  module.exports = { checkPublishConfig, inQuietHours, createQueue };
}
  return module.exports;
